<?php
require_once __DIR__ . '/../includes/bootstrap.php';
require_role('programme_manager');
require_once __DIR__ . '/_management_suite_helpers.php';
$user=current_user();$conn=Database::getConnection();$managerId=(int)($user['id']??$user['user_id']??0);
if($managerId<=0){http_response_code(403);exit('Invalid Programme Manager account.');}
$currentPage='benefits';$pageTitle='Benefits Realisation & Impact Evaluation';$flashes=render_flashes();$errors=[];
$ready=pm_table_exists($conn,'programme_benefits')&&pm_table_exists($conn,'programme_benefit_evaluations');$programmes=pm_suite_programmes($conn,$managerId);$cohorts=pm_suite_cohorts($conn,$managerId);
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!validate_csrf())$errors[]='Session validation failed. Refresh and try again.';
 elseif(!$ready)$errors[]='Import database/programme_stakeholder_benefits.sql before using benefits tracking.';
 else{
  $action=(string)($_POST['action']??'create_benefit');
  if($action==='evaluate'){
   $benefitId=(int)($_POST['benefit_id']??0);$actualRaw=trim((string)($_POST['actual_value']??''));$date=(string)($_POST['evaluation_date']??date('Y-m-d'));$impact=(string)($_POST['impact_rating']??'moderate');$notes=trim((string)($_POST['evaluation_notes']??''));$evidence=trim((string)($_POST['evidence_reference']??''));
   $s=$conn->prepare('SELECT b.* FROM programme_benefits b JOIN programmes p ON p.id=b.programme_id WHERE b.id=? AND p.programme_manager_id=?');$benefit=null;if($s){$s->bind_param('ii',$benefitId,$managerId);$s->execute();$benefit=$s->get_result()->fetch_assoc();$s->close();}
   if(!$benefit)$errors[]='Choose a benefit within your assigned programmes.';if($actualRaw===''||!is_numeric($actualRaw))$errors[]='Enter a numeric actual value.';$actual=(float)$actualRaw;if(abs($actual)>99999999999)$errors[]='Actual value is outside the supported range.';$d=DateTime::createFromFormat('!Y-m-d',$date);if(!$d||$d->format('Y-m-d')!==$date)$errors[]='Choose a valid evaluation date.';if(!in_array($impact,['low','moderate','high','very_high'],true))$errors[]='Choose a valid impact rating.';
   if(!$errors){$baseline=(float)$benefit['baseline_value'];$target=(float)$benefit['target_value'];$direction=$benefit['target_direction'];$reached=$direction==='decrease'?$actual<=$target:$actual>=$target;$delta=$target-$baseline;$progress=abs($delta)<0.000001?($reached?100:0):(($actual-$baseline)/$delta)*100;if($direction==='decrease')$progress=(abs($baseline-$target)<0.000001?($reached?100:0):(($baseline-$actual)/($baseline-$target))*100);$status=$reached?'achieved':($progress>0?'partially_achieved':'not_achieved');$previous=$benefit['actual_value']===null?null:(float)$benefit['actual_value'];$notesValue=$notes?:null;$evidenceValue=$evidence?:null;
    $conn->begin_transaction();$ok=true;$s=$conn->prepare('INSERT INTO programme_benefit_evaluations(benefit_id,evaluation_date,previous_actual,actual_value,benefit_status,impact_rating,evaluation_notes,evidence_reference,evaluated_by) VALUES(?,?,?,?,?,?,?,?,?)');if($s){$s->bind_param('isddssssi',$benefitId,$date,$previous,$actual,$status,$impact,$notesValue,$evidenceValue,$managerId);$ok=$s->execute();$s->close();}else $ok=false;
    if($ok){$s=$conn->prepare('UPDATE programme_benefits SET actual_value=?,benefit_status=?,evidence_reference=? WHERE id=?');if($s){$s->bind_param('dssi',$actual,$status,$evidenceValue,$benefitId);$ok=$s->execute();$s->close();}else $ok=false;}
    if($ok){$conn->commit();set_flash('success','Benefit evaluated','Actual performance and evaluation history have been recorded.');safe_redirect('programme/benefits.php');}else{$conn->rollback();$errors[]='The benefit evaluation could not be saved.';}
   }
  }else{
   $pid=(int)($_POST['programme_id']??0);$cid=(int)($_POST['cohort_id']??0);$name=trim((string)($_POST['benefit_name']??''));$description=trim((string)($_POST['benefit_description']??''));$indicator=trim((string)($_POST['indicator_name']??''));$baselineRaw=trim((string)($_POST['baseline_value']??'0'));$targetRaw=trim((string)($_POST['target_value']??''));$direction=(string)($_POST['target_direction']??'increase');$unit=trim((string)($_POST['measurement_unit']??'value'));$date=trim((string)($_POST['target_date']??''));
   if(!pm_suite_valid_scope($conn,$pid,$cid,$managerId))$errors[]='Choose a programme/cohort within your assigned scope.';if($name===''||mb_strlen($name)>180)$errors[]='Enter a benefit name of up to 180 characters.';if($indicator===''||mb_strlen($indicator)>160)$errors[]='Enter a measurable indicator of up to 160 characters.';if(!is_numeric($baselineRaw)||!is_numeric($targetRaw))$errors[]='Baseline and target must be numeric values.';if(!in_array($direction,['increase','decrease'],true))$errors[]='Choose whether the indicator should increase or decrease.';if($unit===''||mb_strlen($unit)>60)$errors[]='Enter a measurement unit of up to 60 characters.';$targetDate=null;if($date!==''){$d=DateTime::createFromFormat('!Y-m-d',$date);if(!$d||$d->format('Y-m-d')!==$date)$errors[]='Choose a valid target date.';else $targetDate=$date;}
   if(!$errors){$baseline=(float)$baselineRaw;$target=(float)$targetRaw;if(abs($baseline)>99999999999||abs($target)>99999999999)$errors[]='Values are outside the supported range.';else{$cohortValue=$cid?:null;$descriptionValue=$description?:null;$s=$conn->prepare('INSERT INTO programme_benefits(programme_id,cohort_id,benefit_name,benefit_description,indicator_name,baseline_value,target_value,target_direction,measurement_unit,target_date,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?)');if($s){$s->bind_param('iisssddsssi',$pid,$cohortValue,$name,$descriptionValue,$indicator,$baseline,$target,$direction,$unit,$targetDate,$managerId);if($s->execute()){$s->close();set_flash('success','Expected benefit added','The expected benefit and indicator have been saved.');safe_redirect('programme/benefits.php');}$s->close();}$errors[]='The expected benefit could not be saved.';}}
  }
 }
}
$benefits=[];$evaluations=[];$stats=['total'=>0,'achieved'=>0,'partial'=>0,'not_achieved'=>0,'planned'=>0];
if($ready){$s=$conn->prepare('SELECT b.*,p.name programme_name,c.name cohort_name FROM programme_benefits b JOIN programmes p ON p.id=b.programme_id LEFT JOIN cohorts c ON c.id=b.cohort_id WHERE p.programme_manager_id=? ORDER BY b.target_date IS NULL,b.target_date,b.benefit_name');if($s){$s->bind_param('i',$managerId);$s->execute();$benefits=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();}foreach($benefits as $b){$stats['total']++;if($b['benefit_status']==='achieved')$stats['achieved']++;elseif($b['benefit_status']==='partially_achieved')$stats['partial']++;elseif($b['benefit_status']==='not_achieved')$stats['not_achieved']++;else $stats['planned']++;}
 $s=$conn->prepare('SELECT e.*,b.benefit_name,p.name programme_name FROM programme_benefit_evaluations e JOIN programme_benefits b ON b.id=e.benefit_id JOIN programmes p ON p.id=b.programme_id WHERE p.programme_manager_id=? ORDER BY e.evaluation_date DESC,e.id DESC LIMIT 100');if($s){$s->bind_param('i',$managerId);$s->execute();$evaluations=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();}}
function pm_benefit_progress(array $b): float {if($b['actual_value']===null)return 0;$base=(float)$b['baseline_value'];$target=(float)$b['target_value'];$actual=(float)$b['actual_value'];if(abs($target-$base)<0.000001)return ($b['benefit_status']==='achieved'?100:0);$v=$b['target_direction']==='decrease'?(($base-$actual)/($base-$target))*100:(($actual-$base)/($target-$base))*100;return max(0,min(100,$v));}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($pageTitle)?> | Investhood IT</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css"><link rel="stylesheet" href="<?=url('css/styles.css')?>"><link rel="stylesheet" href="<?=url('css/programme_manager_enhancements.css')?>"><link rel="stylesheet" href="<?=url('css/programme_management_suite.css')?>?v=20261125"></head><body class="dashboard-page"><div class="dashboard"><?php require __DIR__.'/sidebar.php';?><main class="dashboard__main"><?php require __DIR__.'/navbar.php';?><div class="pm-suite"><?=$flashes?><section class="pm-suite-hero"><div><span class="pm-suite-eyebrow">Value, outcomes &amp; accountability</span><h1>Benefits Realisation &amp; Impact Evaluation</h1><p>Define measurable programme benefits, compare actual performance against baselines and targets, record evidence and evaluate impact over time.</p></div></section><?php foreach($errors as $error):?><div class="pm-suite-alert"><?=e($error)?></div><?php endforeach;?><?php if(!$ready):?><div class="pm-suite-notice">Import <code>database/programme_stakeholder_benefits.sql</code> to enable benefits realisation and evaluation.</div><?php endif;?>
<section class="pm-suite-kpis"><article class="pm-suite-kpi"><small>Expected benefits</small><strong><?=$stats['total']?></strong><span>Defined across assigned programmes</span></article><article class="pm-suite-kpi"><small>Achieved</small><strong><?=$stats['achieved']?></strong><span>Target reached</span></article><article class="pm-suite-kpi"><small>Partially achieved</small><strong><?=$stats['partial']?></strong><span>Progress recorded, target not reached</span></article><article class="pm-suite-kpi"><small>Not achieved</small><strong><?=$stats['not_achieved']?></strong><span>Target progress not demonstrated</span></article></section>
<div class="pm-suite-grid"><section class="pm-suite-panel"><div class="pm-suite-panel-head"><h2>Define an expected benefit</h2><p>Use an indicator that can be measured consistently and supported by evidence.</p></div><form method="post" class="pm-suite-form"><?=csrf_field()?><input type="hidden" name="action" value="create_benefit"><div class="pm-suite-field"><label>Programme</label><select name="programme_id" required><option value="">Select programme</option><?php foreach($programmes as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?></option><?php endforeach;?></select></div><div class="pm-suite-field"><label>Cohort (optional)</label><select name="cohort_id"><option value="0">Programme-wide</option><?php foreach($cohorts as $c):?><option value="<?=$c['id']?>"><?=e($c['programme_name'].' — '.$c['name'])?></option><?php endforeach;?></select></div><div class="pm-suite-field"><label>Benefit name</label><input name="benefit_name" maxlength="180" required placeholder="e.g. Improved graduate employment rate"></div><div class="pm-suite-field"><label>Description</label><textarea name="benefit_description" rows="3" maxlength="5000"></textarea></div><div class="pm-suite-field"><label>Measurement indicator</label><input name="indicator_name" maxlength="160" required placeholder="e.g. Percentage of graduates employed"></div><div class="pm-suite-two"><div class="pm-suite-field"><label>Baseline value</label><input type="number" step="0.001" name="baseline_value" value="0" required></div><div class="pm-suite-field"><label>Target value</label><input type="number" step="0.001" name="target_value" required></div></div><div class="pm-suite-two"><div class="pm-suite-field"><label>Target direction</label><select name="target_direction"><option value="increase">Increase</option><option value="decrease">Decrease</option></select></div><div class="pm-suite-field"><label>Unit</label><input name="measurement_unit" maxlength="60" value="%" required></div></div><div class="pm-suite-field"><label>Target date</label><input type="date" name="target_date"></div><button class="pm-suite-btn" type="submit" <?=$ready?'':'disabled'?>>Save expected benefit</button></form></section>
<section class="pm-suite-panel"><div class="pm-suite-panel-head"><h2>Evaluate actual performance</h2><p>Each evaluation creates a dated history entry and updates the current benefit status.</p></div><form method="post" class="pm-suite-form"><?=csrf_field()?><input type="hidden" name="action" value="evaluate"><div class="pm-suite-field"><label>Benefit to evaluate</label><select name="benefit_id" required><option value="">Select benefit</option><?php foreach($benefits as $b):?><option value="<?=$b['id']?>"><?=e($b['benefit_name'].' — '.$b['programme_name'].' (target '.$b['target_value'].' '.$b['measurement_unit'].')')?></option><?php endforeach;?></select></div><div class="pm-suite-two"><div class="pm-suite-field"><label>Actual value</label><input type="number" step="0.001" name="actual_value" required></div><div class="pm-suite-field"><label>Evaluation date</label><input type="date" name="evaluation_date" value="<?=date('Y-m-d')?>" required></div></div><div class="pm-suite-field"><label>Impact rating</label><select name="impact_rating"><option value="low">Low</option><option value="moderate" selected>Moderate</option><option value="high">High</option><option value="very_high">Very high</option></select></div><div class="pm-suite-field"><label>Evaluation notes</label><textarea name="evaluation_notes" rows="3" maxlength="5000" placeholder="Explain the measured change, causes, and impact..."></textarea></div><div class="pm-suite-field"><label>Evidence reference</label><input name="evidence_reference" maxlength="190" placeholder="Report, survey, certificate, dataset ID"></div><button class="pm-suite-btn" type="submit" <?=$ready&&$benefits?'':'disabled'?>>Save evaluation</button></form></section></div>
<section class="pm-suite-panel"><div class="pm-suite-panel-head"><h2>Benefits register</h2><p>Progress is calculated from the baseline toward the target; decrease targets are supported too.</p></div><div class="pm-suite-table-wrap"><table class="pm-suite-table"><thead><tr><th>Benefit / Scope</th><th>Indicator</th><th>Baseline</th><th>Target</th><th>Actual</th><th>Progress</th><th>Status / Due</th></tr></thead><tbody><?php if(!$benefits):?><tr><td colspan="7" class="pm-suite-empty">No expected benefits have been defined.</td></tr><?php else:foreach($benefits as $b):$progress=pm_benefit_progress($b);$statusLabels=['planned'=>'Planned','on_track'=>'On track','partially_achieved'=>'Partially achieved','not_achieved'=>'Not achieved','achieved'=>'Achieved'];$statusClass=$b['benefit_status']==='achieved'?'good':($b['benefit_status']==='not_achieved'?'bad':($b['benefit_status']==='partially_achieved'?'warn':'info'));?><tr><td><strong><?=e($b['benefit_name'])?></strong><span class="pm-suite-muted"><?=e($b['programme_name'].' · '.($b['cohort_name']?:'Programme-wide'))?></span></td><td><?=e($b['indicator_name'])?></td><td><?=e($b['baseline_value'].' '.$b['measurement_unit'])?></td><td><?=e($b['target_value'].' '.$b['measurement_unit'])?><span class="pm-suite-muted"><?=e(ucfirst($b['target_direction']))?></span></td><td><?=$b['actual_value']===null?'Not evaluated':e($b['actual_value'].' '.$b['measurement_unit'])?></td><td><strong><?=number_format($progress,1)?>%</strong><div class="pm-suite-progress"><span style="width:<?=$progress?>%"></span></div></td><td><span class="pm-suite-pill <?=$statusClass?>"><?=e($statusLabels[$b['benefit_status']]??'Planned')?></span><span class="pm-suite-muted"><?=e($b['target_date']?date('d M Y',strtotime($b['target_date'])):'No target date')?></span></td></tr><?php endforeach;endif;?></tbody></table></div></section>
<section class="pm-suite-panel"><div class="pm-suite-panel-head"><h2>Impact evaluation history</h2><p>Latest 100 dated evaluations across assigned programmes.</p></div><div class="pm-suite-table-wrap"><table class="pm-suite-table"><thead><tr><th>Date</th><th>Benefit / Programme</th><th>Actual</th><th>Impact</th><th>Status</th><th>Notes / Evidence</th></tr></thead><tbody><?php if(!$evaluations):?><tr><td colspan="6" class="pm-suite-empty">No impact evaluations recorded.</td></tr><?php else:foreach($evaluations as $ev):?><tr><td><?=e(date('d M Y',strtotime($ev['evaluation_date'])))?></td><td><strong><?=e($ev['benefit_name'])?></strong><span class="pm-suite-muted"><?=e($ev['programme_name'])?></span></td><td><?=e($ev['actual_value'])?></td><td><?=e(ucwords(str_replace('_',' ',$ev['impact_rating'])))?></td><td><span class="pm-suite-pill <?= $ev['benefit_status']==='achieved'?'good':($ev['benefit_status']==='not_achieved'?'bad':'warn')?>"><?=e(ucwords(str_replace('_',' ',$ev['benefit_status'])))?></span></td><td><?=e($ev['evaluation_notes']?:'—')?><span class="pm-suite-muted"><?=e($ev['evidence_reference']?:'')?></span></td></tr><?php endforeach;endif;?></tbody></table></div></section></div></main></div><script src="<?=url('js/programme_manager_enhancements.js')?>"></script><script src="<?=url('js/original_pm_sidebar.js')?>"></script></body></html>
